window.MAGIC_CHUNK_55 = [{"name":"Runestone of Power III","aura_strength":"strong","aura_school":"transmutation","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":18000,"weight":0,"description":"A runestone of power is a small chip of polished stone etched with a rune. These objects are potent aids to all spellcasters who cast spontaneously, but not to spellcasters like clerics who have the option to spontaneously cast certain spells. Once per day, a spontaneous caster can draw upon a runestone of power to cast a 3rd-level or lower spell. Doing so is part of the spellcasting action, and expends that runestone's power for the day rather than one of the spellcaster's actual spell slots for the day. An expended runestone of power recharges its capacity after 24 hours.","requirements":"Craft Wondrous Items, creator must be able to spontaneously cast spells of the appropriate spell level","cost":9000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Runestone of Power IV","aura_strength":"strong","aura_school":"transmutation","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":32000,"weight":0,"description":"A runestone of power is a small chip of polished stone etched with a rune. These objects are potent aids to all spellcasters who cast spontaneously, but not to spellcasters like clerics who have the option to spontaneously cast certain spells. Once per day, a spontaneous caster can draw upon a runestone of power to cast a 4th-level or lower spell. Doing so is part of the spellcasting action, and expends that runestone's power for the day rather than one of the spellcaster's actual spell slots for the day. An expended runestone of power recharges its capacity after 24 hours.","requirements":"Craft Wondrous Items, creator must be able to spontaneously cast spells of the appropriate spell level","cost":16000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Runestone of Power V","aura_strength":"strong","aura_school":"transmutation","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":50000,"weight":0,"description":"A runestone of power is a small chip of polished stone etched with a rune. These objects are potent aids to all spellcasters who cast spontaneously, but not to spellcasters like clerics who have the option to spontaneously cast certain spells. Once per day, a spontaneous caster can draw upon a runestone of power to cast a 5th-level or lower spell. Doing so is part of the spellcasting action, and expends that runestone's power for the day rather than one of the spellcaster's actual spell slots for the day. An expended runestone of power recharges its capacity after 24 hours.","requirements":"Craft Wondrous Items, creator must be able to spontaneously cast spells of the appropriate spell level","cost":25000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Runestone of Power VI","aura_strength":"strong","aura_school":"transmutation","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":72000,"weight":0,"description":"A runestone of power is a small chip of polished stone etched with a rune. These objects are potent aids to all spellcasters who cast spontaneously, but not to spellcasters like clerics who have the option to spontaneously cast certain spells. Once per day, a spontaneous caster can draw upon a runestone of power to cast a 6th-level or lower spell. Doing so is part of the spellcasting action, and expends that runestone's power for the day rather than one of the spellcaster's actual spell slots for the day. An expended runestone of power recharges its capacity after 24 hours.","requirements":"Craft Wondrous Items, creator must be able to spontaneously cast spells of the appropriate spell level","cost":36000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Runestone of Power VII","aura_strength":"strong","aura_school":"transmutation","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":98000,"weight":0,"description":"A runestone of power is a small chip of polished stone etched with a rune. These objects are potent aids to all spellcasters who cast spontaneously, but not to spellcasters like clerics who have the option to spontaneously cast certain spells. Once per day, a spontaneous caster can draw upon a runestone of power to cast a 7th-level or lower spell. Doing so is part of the spellcasting action, and expends that runestone's power for the day rather than one of the spellcaster's actual spell slots for the day. An expended runestone of power recharges its capacity after 24 hours.","requirements":"Craft Wondrous Items, creator must be able to spontaneously cast spells of the appropriate spell level","cost":49000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Runestone of Power VIII","aura_strength":"strong","aura_school":"transmutation","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":128000,"weight":0,"description":"A runestone of power is a small chip of polished stone etched with a rune. These objects are potent aids to all spellcasters who cast spontaneously, but not to spellcasters like clerics who have the option to spontaneously cast certain spells. Once per day, a spontaneous caster can draw upon a runestone of power to cast an 8th-level or lower spell. Doing so is part of the spellcasting action, and expends that runestone's power for the day rather than one of the spellcaster's actual spell slots for the day. An expended runestone of power recharges its capacity after 24 hours.","requirements":"Craft Wondrous Items, creator must be able to spontaneously cast spells of the appropriate spell level","cost":64000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Runestone of Power IX","aura_strength":"strong","aura_school":"transmutation","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":162000,"weight":0,"description":"A runestone of power is a small chip of polished stone etched with a rune. These objects are potent aids to all spellcasters who cast spontaneously, but not to spellcasters like clerics who have the option to spontaneously cast certain spells. Once per day, a spontaneous caster can draw upon a runestone of power to cast a 9th-level or lower spell. Doing so is part of the spellcasting action, and expends that runestone's power for the day rather than one of the spellcaster's actual spell slots for the day. An expended runestone of power recharges its capacity after 24 hours.","requirements":"Craft Wondrous Items, creator must be able to spontaneously cast spells of the appropriate spell level","cost":81000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Saboteur's Goggles","aura_strength":"moderate","aura_school":"enchantment","cl":7,"slots":["eyes"],"groups":["Wondrous Item"],"price":16000,"weight":0,"description":"These goggles are fitted with crimson lenses surrounded by thick, round brass frames and secured with a leather strap. Three times per day, the wearer can use murderous command as a gaze attack (Will DC 16 negates).","requirements":"Craft Wondrous Items, Heighten Spell, murderous command","cost":8000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Scabbard of Many Blades","aura_strength":"moderate","aura_school":"conjuration","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":5000,"weight":3,"description":"This scabbard can hold multiple melee weapons in an extradimensional space, including weapons that would not normally fit in any kind of scabbard or sheath. It can hold up to four two-handed weapons. Two one-handed or light melee weapons can fit in each two-handed weapon slot, for a maximum capacity of eight one-handed or light melee weapons. Only weapons designed to be used by creatures the same size as the wearer or smaller can be kept in a scabbard of many blades. The scabbard can't be used to store shields (even if they can be used to make melee attacks), gauntlets, improvised weapons, or wands, but can store rods (which are treated as one-handed weapons) and magic staves (which are treated as two-handed weapons). When the wearer draws a weapon from the scabbard, if he doesn't lose his grip on it (keeping it in his hands at all times), as a move action he can have it switch places with another weapon in the scabbard. If the wearer has the Quick Draw feat, he can do this as a swift action. If the wearer loses his grip on a weapon drawn from the scabbard, that weapon can't switch places with another weapon until it has been, sheathed in the scabbard of many blades and drawn again.","requirements":"Craft Wondrous Items, secret chest","cost":2500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Skullcrusher Gauntlets","aura_strength":"moderate","aura_school":"evocation","cl":10,"slots":["hands"],"groups":["Wondrous Item"],"price":15302,"weight":6,"description":"These bloodstained gauntlets are made of a combination of blackened steel and polished white stone. They are slightly oversized and somewhat bulky, though still suitable for combat. They function as +1 gauntlets. Once per day, the wearer can unleash a devastating attack with the gauntlets that can instantly knock a target unconscious. The wearer must announce his intent before making his attack roll, and creatures immune to critical hits can't be affected. To make the attack, the wearer makes a single melee attack at his highest base attack bonus as a full-round action. If the strike hits, the target takes 4d6 points of force damage and must succeed at a DC 15 Fortitude save or fall unconscious until the end of its next turn. Even if the target succeeds at the Fortitude save, it is staggered until the end of its next turn. When worn by a brawler with the knockout class feature, the DC to resist the brawler's knockout increases by 2.","requirements":"Craft Wondrous Items, deep slumber, stone fist","cost":7802,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Slayer's Robe","aura_strength":"moderate","aura_school":"divination","cl":9,"slots":["body"],"groups":["Wondrous Item"],"price":15000,"weight":5,"description":"This ragged, brown robe could be mistaken for a monk's cassock, but the devotees who wear it are dedicated only to the art of killing. This robe grants the wearer a +5 competence bonus on Stealth checks and Sleight of Hand checks to conceal a weapon, and a +1 resistance bonus on all saving throws. If worn by a slayer, the resistance bonus on saving throws increases to match the slayer's studied target bonus when he is facing a studied target. On command, the robe's wearer is able to turn into a brown mist (as the gaseous form spell) for up to 5 minutes per day. This duration doesn't need to be continuous, but must be used in 1-minute increments. While the wearer is in this form, the bonus on Stealth checks increases to +10. The wearer can end this effect as a standard action.","requirements":"Craft Wondrous Items, gaseous form, guidance","cost":7500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, I","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":1000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of a 1st-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, II","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":4000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of a 2nd-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":2000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, III","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":9000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of a 3rd-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":4500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, IV","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":16000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of a 4th-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":8000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, V","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":25000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of a 5th-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":12500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, VI","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":36000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of a 6th-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":18000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, VII","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":49000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of a 7th-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":24500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, VIII","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":64000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of an 8th-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":32000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Spell Lattice, IX","aura_strength":"varies","aura_school":"see text","cl":17,"slots":["none"],"groups":["Wondrous Item"],"price":81000,"weight":1,"description":"A spell lattice is a block of transparent crystal, internally etched with a three-dimensional representation of a 9th-level spell. This spell is chosen when the item is created. The contained spell determines the school of the lattice's aura.\n\nWhen a spell lattice is wielded by a spontaneous spellcaster who has the spell contained within it on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells known. When an arcanist holds a spell lattice, as long as he has the contained spell on his class spell list, he can use his spell slots to cast that spell as if it were one of his spells currently prepared.\n\nA spellcaster who uses a spellbook or formula book can copy the spell from a spell lattice as if it were a scroll. Doing so expends the spell from the spell lattice.","requirements":"Craft Wondrous Items, Scribe Scroll, creator must be able to cast the spell placed in the spell lattice","cost":40500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Storyteller's Dust","aura_strength":"faint","aura_school":"illusion","cl":2,"slots":["none"],"groups":["Wondrous Item"],"price":600,"weight":0,"description":"This dust is kept in gaudy bags, but is a simple white powder. When thrown into a fire, it conjures a visible theater of the mind (as minor image) within a 10-foot cube above the flames. The user can manipulate this illusion, which lasts for 2 hours or until the user banishes the scene. The user gains a +2 bonus on all Performance checks to tell a story using the image created by the dust.","requirements":"Craft Wondrous Items, minor image","cost":300,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Swordmaster's Flair","aura_strength":"faint","aura_school":"enchantment","cl":5,"slots":["none"],"groups":["Wondrous Item"],"price":2500,"weight":0,"description":"These garish tokens usually take the form of a colorful clothing accessories. So long as a token is grasped in the user's off hand, he can spend 1 panache point to gain the use of a specific ability associated with the token. Once per day, the bearer can use the token to gain the full benefit of the token without spending panache. Non-swashbucklers can use the tokens, but unless they have another way of gaining panache, they can use the ability only once per day. A character can benefit from only one token at a time; holding a second token provides no additional benefit. There are four types of tokens, each offering a different benefit. Blue Scarf: The user can spend 1 panache point as a swift action to increase his melee reach with light or one-handed piercing weapons by 5 feet for 1 minute. Green Glove: The user can spend 1 panache point as a swift action to ignore the effects of difficult terrain until the end of her next turn. Red Sash: The user can spend 1 panache point as an immediate action to attempt a combat maneuver check to trip a creature that has charged and ended its charge in a space within the user's melee reach. This combat maneuver doesn't provoke an attack of opportunity, it's attempted before the attack at the end of the charge, and the sash's user gains a +2 bonus on the check. If the check is successful, the attacker can't make an attack at the end of its charge. White Lace Kerchief: The user can spend 1 panache point as a swift action to pinpoint an unseen, adjacent enemy and gains the benefits of the Blind Fight feat for 1 round.","requirements":"Blind Fight, Craft Wondrous Items, Improved Trip, Lunge, Nimble Moves, good hope","cost":1250,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Figurine of Wondrous Power, Tin Imp","aura_strength":"moderate","aura_school":"enchantment and transmutation","cl":11,"slots":["none"],"groups":["Wondrous Item"],"price":13000,"weight":1,"description":"These fat, smirking imp figurines are made of solid tin. A tin imp turns into an imp on command, though it retains its metallic consistency, which gives it a +4 armor bonus to AC. In imp form, a tin imp can turn invisible at will as a swift action, though it retains none of an imp's other spell-like abilities and lacks a poisoned sting. Tin imps generally avoid combat, but make excellent spies and trackers. The tin imp's owner can, as a move action, designate a single creature in his line of sight as the tin imp's quarry. The tin imp then follows its quarry clandestinely, and sends a whispered message to its owner once each hour detailing the quarry's location and activities. The message is similar to the whispering wind spell, though the message unerringly locates the tin imp's owner instead of moving to a predetermined location. A tin imp can maintain its animate status for up to 48 hours per week. This duration doesn't need to be continuous, but must be used in 1-hour increments. If slain in combat, a tin imp is destroyed. Additionally, a creature with the track class feature can command a tin imp he owns to study a set of footprints (a standard action) and designate the creature that made the footprints as its quarry. The tin imp can then attempt to track the creature as if its owner was tracking it, using the owner's Perception and Survival skill (and any tracking bonuses).","requirements":"Craft Wondrous Items, animate objects, invisibility, whispering wind","cost":6500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Toothpick of Pyrotechnics","aura_strength":"faint","aura_school":"evocation","cl":3,"slots":["none"],"groups":["Wondrous Item"],"price":400,"weight":0,"description":"This wooden toothpick is useful for creating flashy diversions on stage or in a fight. Breaking the toothpick causes a blinding flash and a dark cloud of smoke to appear. Creatures other than the user within 20 feet must succeed at a DC 13 Fortitude save or be blinded for 1d4+1 rounds. The cloud of smoke spreads 20 feet in all directions, obscures all sight (including darkvision), and lasts for 3 rounds.","requirements":"Craft Wondrous Items, pyrotechnics","cost":200,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Torc of Bloody Rage","aura_strength":"moderate","aura_school":"transmutation","cl":7,"slots":["neck"],"groups":["Wondrous Item"],"price":8000,"weight":1,"description":"This thick iron torc appears crudely made, and a few dents from the maker's hammer are visible. Once per day as a free action, the wearer can enter a rage for 6 rounds as the spell, except that the wearer is fatigued for 12 rounds after the rage ends. If the wearer has the rage class feature, once per day as a free action the wearer can grant himself 3 additional rounds of rage instead.","requirements":"Craft Wondrous Items, rage, creator must have the bloodrage or rage class feature","cost":4000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Torc of the Primal Song","aura_strength":"moderate","aura_school":"enchantment","cl":9,"slots":["neck"],"groups":["Wondrous Item"],"price":6000,"weight":4,"description":"This heavy gold neck ring resembles a braided rope. When the wearer performs a raging song or benefits from an ally's raging song, he gains the Diehard feat for the duration of the song. In addition, he benefits from any helpful raging song or bardic performance for 1 round after the performance ends or would normally cease affecting the wearer. This doesn't stack with other means of prolonging the effects of a performance that has ended.","requirements":"Craft Wondrous Items, greater heroism","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Trollbone","aura_strength":"moderate","aura_school":"conjuration","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":2400,"weight":1,"description":"Runic engravings adorn this charred rib bone pulled from a slain troll. When the bone is tossed up to 20 feet away, it can grow into a full-sized troll under the user's control on command. The troll normally remains for 2d4 rounds, but if the user is maintaining a bardic performance when the item is activated, the duration is extended until the end of the performance. When the troll is slain or the duration ends, it turns back into a bone that then crumbles into dust.","requirements":"Craft Wondrous Items, summon monster IV","cost":1200,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Vanishing Sheath","aura_strength":"moderate","aura_school":"conjuration","cl":6,"slots":["wrists"],"groups":["Wondrous Item"],"price":5000,"weight":1,"description":"This small sheath attaches to the wrist with a leather strap. The sheath can accommodate any single light weapon, wand, or piece of ammunition weighing no more than 5 pounds. While sheathed, the weapon is hidden in an extradimensional space and is weightless. As a swift action, the wearer can flex his wrist, ejecting the weapon into his hand. If his hand isn't empty, the weapon remains sheathed. Stowing a weapon in the sheath requires a move action. The wearer gains a +4 bonus on any Sleight of Hand check to oppose the Perception check of someone observing or frisking the wearer in search of a weapon in the sheath. Vanishing sheaths can be worn in pairs-one on each arm. A person wearing two vanishing sheaths can eject either or both weapons with a single swift action.","requirements":"Craft Wondrous Items, secret chest","cost":2500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Wand Key Ring","aura_strength":"faint","aura_school":"universal","cl":5,"slots":["none"],"groups":["Wondrous Item"],"price":3000,"weight":8,"description":"Each of these rune-carved brass rings is keyed to a specific spell at creation. When using the Use Magic Device skill to activate a scroll or spell trigger item based on that spell, the bearer gains a +10 insight bonus on the skill check.","requirements":"Craft Wondrous Items, guidance, creator must have 10 ranks in the Use Magic Device skill","cost":1500,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Whistle of Calling","aura_strength":"moderate","aura_school":"conjuration","cl":7,"slots":["none"],"groups":["Wondrous Item"],"price":6300,"weight":0,"description":"This whistle emits a loud, shrill note. Once per day when the user blows this whistle his mount or animal companion is instantly teleported to a safe space of the user's choice that's within 30 feet of him. The creature must be within 1 mile, and any effect that bars or hampers teleportation also impedes this effect. The whistle is useless unless attuned to a specific mount or animal companion; attuning the whistle is a special ritual that takes 10 minutes. The whistle can be attuned to a new mount or animal companion at will.","requirements":"Craft Wondrous Items, teleport","cost":3150,"destruction":null,"base_item":null,"magic_items":null,"source":"Advanced Class Guide","pfs_content":0},{"name":"Cauldron of Transmutation","aura_strength":"strong","aura_school":"transmutation","cl":13,"slots":["none"],"groups":["Wondrous Item"],"price":33000,"weight":15,"description":"This small brass cauldron is engraved with arcane runes, and its bottom is blackened by fire. To function, the cauldron must be filled with pure water and heated from below. When any two potions are emptied into the cauldron, they are transmuted into a single potion, the spell level of which must be equal to or lower than that of the component potion with the lower spell level. The user of the cauldron must designate which potion is to be created when the process begins. The entire process takes 1 minute per spell level of the potion being created.","requirements":"Craft Wondrous Items, polymorph any object","cost":16500,"destruction":null,"base_item":null,"magic_items":null,"source":"Undead Unleashed","pfs_content":0},{"name":"Rixbrand","aura_strength":"moderate","aura_school":"conjuration and evocation","cl":10,"slots":["none"],"groups":["Weapon"],"price":90000,"weight":8,"description":"Arnlaugr's legendary blade, Rixbrand, is a double-sided blade of folded blue steel, intricately engraved with ancient runes that light up with electric flame in the presence of dragonkind. The hilt is inlaid with ebony and wrapped with silver wire; the pommel features two silvered dragon heads. Rixbrand is a +3 wounding dragon-bane greatsword. When the blade scores a critical hit on a dragon, the dragon heads on its pommel spit boiling acid into the wound hewn by the blade. This deals an additional 1d10 points of acid damage and 1d10 points of fire damage to the dragon. Rixbrand's wielder gains a +4 resistance bonus on all saving throws against breath weapons, spell-like abilities, and spells from dragons. Since Arnlaugr's death, several duplicates of the legendary sword have been created. These blades have been wielded by mercenaries and adventurers alike, although they tend to end up in dragon hoards when their would-be dragonslayer wielders tackle something beyond their ability to endure even with the blade in hand-the same fate that befell the original sword in Arnlaugr's hands.","requirements":"Craft Magic Arms and Armor, bleed, summon monster I","cost":45000,"destruction":null,"base_item":"+3 wounding dragon-bane greatsword","magic_items":null,"source":"Undead Unleashed","pfs_content":0},{"name":"Void Funnel","aura_strength":"strong","aura_school":"conjuration","cl":18,"slots":["none"],"groups":["Wondrous Item"],"price":46000,"weight":10,"description":"This elaborately tapered lattice of adamantine and copper channels the essence of one plane to which it has been attuned. Whenever it leaves a plane of existence, it becomes attuned to one planar trait from among the following that the plane possessed: minor negative-dominant, minor positive-dominant, mildly aligned. If a plane had multiple appropriate traits, one is chosen randomly. If the plane has a more powerful version of one of these traits, the item attunes to the weaker version of the trait. Once per day, when a command word is spoken, the area within a 30-foot-radius emanation centered on the funnel gains the attuned trait for 1 minute. If the user of a void funnel chooses, he becomes immune to any negative effects of the funnel when it's activated.","requirements":"Craft Wondrous Items, gate","cost":23000,"destruction":null,"base_item":null,"magic_items":null,"source":"Undead Unleashed","pfs_content":0},{"name":"Void Crystal","aura_strength":"strong","aura_school":"necromancy","cl":15,"slots":["none"],"groups":["Artifact, Minor"],"price":0,"weight":160,"description":"The void crystal crackled into existence through interplanetary feedback between a device on Golarion-one of two linked magical rings-and a facility on Eox. The ring that's buried deep beneath the Dim Gate sits at the center of this great crystal, which shudders and expands in the collection chamber each time the proper alignment of celestial bodies comes to pass. The void crystal is attuned to the creature that wears its control ring, which is inherently linked to the ring at the center of the crystal. As a move action, a creature wearing the ring can trigger the crystal to discharge negative energy. This discharge fills the chamber, and deals 150 points of negative energy damage (Will DC 20 half). Undead creatures in the area of the discharge are healed of 150 points of damage. The reservoirs in the Dim Gate usually contain enough energy to power this discharge three times per week. Also, a creature in control of the void crystal can use its necromantic energy to raise any creature killed by the discharge as an undead creature as if using animate dead, create undead, or create greater undead. The creature in control of the void crystal can control up to 30 HD of undead created in this manner. Finally, a creature in control of the void crystal can use dimension door at will to travel to the collection chamber or the Dim Gate's control room.","requirements":null,"cost":0,"destruction":"The void crystal can be destroyed by subjecting it to 16 continual hours of true sunlight without removing it from its receptacle in the collection chamber.","base_item":null,"magic_items":null,"source":"Undead Unleashed","pfs_content":0},{"name":"Ghost Mirror","aura_strength":"faint","aura_school":"divination and evocation","cl":3,"slots":["none"],"groups":["Wondrous Item"],"price":3000,"weight":0.5,"description":"This small hand mirror is warped and tarnished around the edges. A creature wielding the mirror can activate it by speaking a command word as a standard action. Once activated, the mirror grants the wielder the ability to see all undead within 60 feet clearly reflected in the mirror. This includes ethereal undead and incorporeal undead hiding in objects or walls of up to 5 feet in thickness. A ghost mirror doesn't confer any ability to see such creatures directly, only their mirrored reflections, and grants creatures seen in it concealment (50% miss chance). A ghost mirror can be used for 3 minutes per day. These uses don't need to be consecutive but must be used in 1-minute increments.","requirements":"Craft Wondrous Items, detect undead","cost":1500,"destruction":null,"base_item":null,"magic_items":null,"source":"Undead Unleashed","pfs_content":0},{"name":"Hemnetep's Chariot","aura_strength":"moderate","aura_school":"transmutation","cl":9,"slots":["none"],"groups":["Wondrous Item"],"price":45000,"weight":0.5,"description":"This miniature chariot is made of wood and bronze and has a leather thong so it can hang around the neck or a belt. Once per day when the command word is spoken, the chariot increases in size to a fully functioning medium chariot capable of holding one Large creature or four Medium creatures. Up to four Medium creatures or one Large creature can be harnessed to the chariot to pull it, allowing these creatures as well as the chariot to gain the effects of overland flight. The chariot cannot move of its own volition and must have a source of propulsion in order to fly. With a second command word, the chariot shrinks back to its miniature size. Any creatures harnessed to it (but not those riding the vehicle) are absorbed into the miniature chariot. Such creatures are affected as if by a temporal stasis spell; they reappear at their normal size when the chariot is next activated.","requirements":"Craft Wondrous Items, overland flight, shrink item","cost":22500,"destruction":null,"base_item":null,"magic_items":null,"source":"Undead Unleashed","pfs_content":0},{"name":"Shepsi-Ak's Funerary Mask","aura_strength":"moderate","aura_school":"varies","cl":9,"slots":["head"],"groups":["Wondrous Item"],"price":9000,"weight":1,"description":"An undead wearing this golden mask is treated as both an undead and a creature of the type it was before becoming undead (including any associated subtypes) for the purposes of determining its eligibility as a target of illusion and transmutation spells (such as alter self or disguise self). A corpse wearing the mask gains the effects of gentle repose and sanctify corpse. A living creature wearing the mask gains no effects.","requirements":"Craft Wondrous Items, polymorph, sanctify corpse","cost":4500,"destruction":null,"base_item":null,"magic_items":null,"source":"Undead Unleashed","pfs_content":0},{"name":"Body Piercings, Minor","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["body"],"groups":["Shadow Piercing"],"price":1800,"weight":0,"description":"These piercings come in the form of grotesque spikes and needles that cover every inch of the wearer's skin. Minor: The wearer gains a +2 competence bonus to CMD against grappling attempts. Major: Any creature attacking the wearer with a natural or unarmed attack must succeed at a DC 15 Reflex save or take 1d4 points of damage. Greater: The wearer is considered to have +1 armor spikes when not wearing armor or bulky clothing, and is considered proficient with armor spikes.","requirements":"Craft Shadow Piercing, Improved Grapple, magic weapon","cost":900,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Body Piercings, Major","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["body"],"groups":["Shadow Piercing"],"price":2400,"weight":0,"description":"These piercings come in the form of grotesque spikes and needles that cover every inch of the wearer's skin. Minor: The wearer gains a +2 competence bonus to CMD against grappling attempts. Major: Any creature attacking the wearer with a natural or unarmed attack must succeed at a DC 15 Reflex save or take 1d4 points of damage. Greater: The wearer is considered to have +1 armor spikes when not wearing armor or bulky clothing, and is considered proficient with armor spikes.","requirements":"Craft Shadow Piercing, Improved Grapple, magic weapon","cost":1200,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Body Piercings, Greater","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["body"],"groups":["Shadow Piercing"],"price":3200,"weight":0,"description":"These piercings come in the form of grotesque spikes and needles that cover every inch of the wearer's skin. Minor: The wearer gains a +2 competence bonus to CMD against grappling attempts. Major: Any creature attacking the wearer with a natural or unarmed attack must succeed at a DC 15 Reflex save or take 1d4 points of damage. Greater: The wearer is considered to have +1 armor spikes when not wearing armor or bulky clothing, and is considered proficient with armor spikes.","requirements":"Craft Shadow Piercing, Improved Grapple, magic weapon","cost":1600,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Chest Piercings, Minor","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["body"],"groups":["Shadow Piercing"],"price":2200,"weight":0,"description":"These excruciating body ornaments come in the form of sharp barbs and serrated rings inserted in the nipples, abdomen, or along the ribs. The pain they cause sharpens the mind and blocks out distractions. Minor: The wearer gains a +2 profane bonus on saves against effects that cause the dazed, nauseated, and sickened conditions. Major: The wearer gains a +5 competence bonus on concentration checks. Greater: The wearer gains a +4 profane bonus on saving throws against effects that deal ability damage or drain.","requirements":"Craft Shadow Piercing, bear's endurance","cost":1100,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Chest Piercings, Greater","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["body"],"groups":["Shadow Piercing"],"price":5750,"weight":0,"description":"These excruciating body ornaments come in the form of sharp barbs and serrated rings inserted in the nipples, abdomen, or along the ribs. The pain they cause sharpens the mind and blocks out distractions. Minor: The wearer gains a +2 profane bonus on saves against effects that cause the dazed, nauseated, and sickened conditions. Major: The wearer gains a +5 competence bonus on concentration checks. Greater: The wearer gains a +4 profane bonus on saving throws against effects that deal ability damage or drain.","requirements":"Craft Shadow Piercing, bear's endurance","cost":2875,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Chest Piercings, Major","aura_strength":"faint","aura_school":"transmutation","cl":3,"slots":["body"],"groups":["Shadow Piercing"],"price":3750,"weight":0,"description":"These excruciating body ornaments come in the form of sharp barbs and serrated rings inserted in the nipples, abdomen, or along the ribs. The pain they cause sharpens the mind and blocks out distractions. Minor: The wearer gains a +2 profane bonus on saves against effects that cause the dazed, nauseated, and sickened conditions. Major: The wearer gains a +5 competence bonus on concentration checks. Greater: The wearer gains a +4 profane bonus on saving throws against effects that deal ability damage or drain.","requirements":"Craft Shadow Piercing, fox's cunning","cost":1875,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Eye Piercings, Minor","aura_strength":"faint","aura_school":"transmutation","cl":5,"slots":["eyes"],"groups":["Shadow Piercing"],"price":6000,"weight":0,"description":"These piercings may penetrate the eyebrow, eyelid, or the eye itself. Due to magical, they don't impair the owner's vision. All effects from an eye piercing are continuous. Minor: The wearer gains low-light vision. If the wearer already has low-light vision, the ability's range is doubled. Major: The wearer gains darkvision to 60 feet. Greater: The wearer gains the see in darkness special ability.","requirements":"Craft Shadow Piercing, keen senses","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Eye Piercings, Major","aura_strength":"faint","aura_school":"transmutation","cl":5,"slots":["eyes"],"groups":["Shadow Piercing"],"price":18000,"weight":0,"description":"These piercings may penetrate the eyebrow, eyelid, or the eye itself. Due to magical, they don't impair the owner's vision. All effects from an eye piercing are continuous. Minor: The wearer gains low-light vision. If the wearer already has low-light vision, the ability's range is doubled. Major: The wearer gains darkvision to 60 feet. Greater: The wearer gains the see in darkness special ability.","requirements":"Craft Shadow Piercing, darkvision","cost":9000,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Eye Piercings, Greater","aura_strength":"faint","aura_school":"transmutation","cl":5,"slots":["eyes"],"groups":["Shadow Piercing"],"price":32000,"weight":0,"description":"These piercings may penetrate the eyebrow, eyelid, or the eye itself. Due to magical, they don't impair the owner's vision. All effects from an eye piercing are continuous. Minor: The wearer gains low-light vision. If the wearer already has low-light vision, the ability's range is doubled. Major: The wearer gains darkvision to 60 feet. Greater: The wearer gains the see in darkness special ability.","requirements":"Craft Shadow Piercing, darkvision","cost":16000,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Head Piercings, Minor","aura_strength":"faint","aura_school":"transmutation","cl":5,"slots":["head"],"groups":["Shadow Piercing"],"price":3750,"weight":0,"description":"Whether they are crowns of pins, pinned-back lips, or simple nose rings, these piercings accentuate the owner's terrifying presence and inner resolve. Minor: The wearer gains a +5 competence bonus on Intimidate checks.\n\nMajor: The wearer gains a +4 profane bonus against mind-affecting effects. Greater: The wearer can use fear twice per day (Will DC 16).","requirements":"Craft Shadow Piercing, fear","cost":1875,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Head Piercings, Greater","aura_strength":"faint","aura_school":"transmutation","cl":5,"slots":["head"],"groups":["Shadow Piercing"],"price":33600,"weight":0,"description":"Whether they are crowns of pins, pinned-back lips, or simple nose rings, these piercings accentuate the owner's terrifying presence and inner resolve. Minor: The wearer gains a +5 competence bonus on Intimidate checks.\n\nMajor: The wearer gains a +4 profane bonus against mind-affecting effects. Greater: The wearer can use fear twice per day (Will DC 16).","requirements":"Craft Shadow Piercing, fear","cost":16800,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Head Piercings, Major","aura_strength":"faint","aura_school":"transmutation","cl":5,"slots":["head"],"groups":["Shadow Piercing"],"price":6000,"weight":0,"description":"Whether they are crowns of pins, pinned-back lips, or simple nose rings, these piercings accentuate the owner's terrifying presence and inner resolve. Minor: The wearer gains a +5 competence bonus on Intimidate checks.\n\nMajor: The wearer gains a +4 profane bonus against mind-affecting effects. Greater: The wearer can use fear twice per day (Will DC 16).","requirements":"Craft Shadow Piercing, owl's wisdom","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0},{"name":"Suspension Piercings, Minor","aura_strength":"faint","aura_school":"transmutation","cl":7,"slots":["belt","shoulders"],"groups":["Shadow Piercing"],"price":6000,"weight":0,"description":"These piercings are popular among suspensionists, who hang from hooks attached to their skin. Minor: The wearer gains feather fall as a continuous effect. Major: The wearer may use levitate twice per day. Greater: The wearer may use air walk once per day.","requirements":"Craft Shadow Piercing, feather fall","cost":3000,"destruction":null,"base_item":null,"magic_items":null,"source":"Champions of Corruption","pfs_content":0}];
